#!/usr/bin/env python3
"""Visible Design 2.0 product shell. Lightweight, dependency-free, same workspace/canvas APIs."""

def install(html):
    css=r'''<style id="dore-design2-ui">
:root{--d2-bg:#171816;--d2-panel:#f4f1e9;--d2-paper:#fbfaf6;--d2-ink:#24231f;--d2-muted:#777269;--d2-line:#d9d3c7;--d2-gold:#b49a55}.top{height:52px!important;background:#11120f!important;border:0!important;padding:0 16px!important;gap:5px!important}.top strong{font-family:Georgia,"Times New Roman",serif;font-size:16px;font-weight:400;letter-spacing:.03em}.top strong:after{content:"  2.0";color:var(--d2-gold);font:10px Inter,sans-serif;letter-spacing:.14em}.top button,.top a{border:0!important;background:transparent!important;color:#aaa!important;border-radius:5px;padding:7px 9px!important}.top button:hover,.top a:hover{background:#24251f!important;color:white!important}.status{font:10px ui-monospace,monospace;color:#c6b06d!important}.work{height:calc(100% - 52px)!important;grid-template-columns:258px minmax(0,1fr) 286px!important}.side{background:var(--d2-panel)!important;border-color:var(--d2-line)!important;padding:16px 14px!important}.side h3{font:600 9px Inter,sans-serif!important;letter-spacing:.16em;color:#8b8579;margin:16px 4px 8px!important}.side h3:first-child{margin-top:0!important}.page{border:0!important;background:transparent!important;border-radius:7px;margin:2px 0!important;padding:9px 10px!important;font-family:Inter,sans-serif!important}.page:hover{background:#ebe6dc!important}.page.active{border:0!important;background:#ded6c5!important;box-shadow:inset 2px 0 var(--d2-gold)}.page b{font-size:12px;font-weight:600}.page small{margin-top:3px;display:block;font-size:9px;color:#8a8479}.layer{border:0!important;border-radius:5px;padding:7px 9px!important;font-size:10px;color:#59554d}.layer:hover,.layer.active{background:#e6dfd1!important}.canvaswrap{position:relative;background:#292a27!important;padding:32px!important}.canvaswrap:before{content:"CANVAS";position:absolute;top:10px;left:16px;color:#777;font:8px Inter,sans-serif;letter-spacing:.18em}.canvas{border-radius:2px;box-shadow:0 18px 60px #0007!important;transform-origin:top left}.right label{font:600 8px Inter,sans-serif!important;letter-spacing:.13em;color:#999187!important}.right textarea{border:1px solid var(--d2-line)!important;border-radius:6px;background:var(--d2-paper);font:13px/1.5 Inter,sans-serif!important}.right button{border-radius:6px!important;background:#272721!important}.hint{font:11px/1.55 Inter,sans-serif!important;color:#817b71!important}.candidate-card{background:transparent!important;color:var(--d2-ink)!important;border:1px solid var(--d2-line)!important;border-radius:6px!important}.candidate-card.on{outline:1px solid var(--d2-gold)!important}.candidate-card small{color:#9b854c!important}
#d2-rail{position:fixed;z-index:20;left:50%;bottom:17px;transform:translateX(-50%);display:flex;gap:3px;padding:5px;background:#11120fe8;border:1px solid #393a35;border-radius:9px;box-shadow:0 8px 24px #0005}#d2-rail button{min-width:34px;height:30px;border:0;border-radius:5px;background:transparent;color:#aaa;font:13px Inter,sans-serif;cursor:pointer;padding:0 8px}#d2-rail button:hover{background:#30312c;color:#fff}#d2-rail .on{color:#d1b86f;background:#2b2b25}#d2-zoom{font:10px ui-monospace,monospace!important;color:#cfc9bb!important;border-left:1px solid #3b3c37!important;margin-left:3px!important}
#d2-dore{position:fixed;z-index:21;right:302px;top:62px;padding:6px 9px;border:1px solid #494a44;border-radius:999px;background:#171814d9;color:#cbb675;font:9px Inter,sans-serif;letter-spacing:.08em;pointer-events:none}
#d2-command{position:fixed;z-index:100;inset:0;background:#0006;display:none;align-items:flex-start;justify-content:center;padding-top:14vh}#d2-command.open{display:flex}#d2-command-box{width:min(560px,70vw);background:#f7f3ea;border:1px solid #d4cbbb;border-radius:10px;box-shadow:0 28px 80px #0008;overflow:hidden}#d2-command input{width:100%;border:0;border-bottom:1px solid #ddd4c5;padding:15px 16px;font:14px Inter,sans-serif;background:#fffaf0;outline:0}#d2-command-list button{display:flex;width:100%;justify-content:space-between;border:0;background:transparent;padding:11px 16px;text-align:left;font:12px Inter,sans-serif;color:#2d2b26;cursor:pointer}#d2-command-list button:hover{background:#e9e1d2}#d2-command-list kbd{font:9px ui-monospace,monospace;color:#8c8578}
</style>'''
    shell=r'''<div id="d2-dore">DORÉ · SAME ARTIFACT</div><div id="d2-rail" aria-label="Canvas tools"><button data-tool="select" class="on" title="Select (V)">↖</button><button data-tool="frame" title="Frame (F)">□</button><button data-tool="text" title="Text (T)">T</button><button data-tool="asset" title="Asset (A)">◇</button><button id="d2-command-open" title="Command (⌘K)">⌘</button><button id="d2-zoom">100%</button></div><div id="d2-command"><div id="d2-command-box"><input id="d2-command-input" placeholder="Search Design commands…"><div id="d2-command-list"><button data-cmd="refresh">Refresh workspace <kbd>⌘R</kbd></button><button data-cmd="verify">Verify design <kbd>VFY</kbd></button><button data-cmd="preview">Preview page <kbd>P</kbd></button><button data-cmd="fit">Fit canvas <kbd>0</kbd></button><button data-cmd="actual">Actual size <kbd>1</kbd></button><button data-cmd="multiwrite">Open 多寫 <kbd>M</kbd></button></div></div></div>'''
    js=r'''<script id="d2-ui-js">(()=>{let tool='select',zoom=1;const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)],canvas=()=>q('#canvas');function setTool(t){tool=t;qa('#d2-rail [data-tool]').forEach(b=>b.classList.toggle('on',b.dataset.tool===t));q('#status').textContent='tool · '+t+' · '+active}function setZoom(z){zoom=Math.max(.25,Math.min(2,z));const c=canvas();c.style.transform='scale('+zoom+')';c.style.width=(100/zoom)+'%';c.style.height=(100/zoom)+'%';q('#d2-zoom').textContent=Math.round(zoom*100)+'%'}function toggleCmd(on){q('#d2-command').classList.toggle('open',on);if(on){q('#d2-command-input').value='';q('#d2-command-input').focus();filterCmd('')}}function filterCmd(v){const s=v.toLowerCase();qa('#d2-command-list button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(s))}function run(c){toggleCmd(false);if(c==='refresh')q('#refresh').click();if(c==='verify')q('#verify').click();if(c==='preview')q('#preview').click();if(c==='fit')setZoom(.8);if(c==='actual')setZoom(1);if(c==='multiwrite')switchPage('multiwrite-home')}qa('#d2-rail [data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));q('#d2-command-open').onclick=()=>toggleCmd(true);q('#d2-zoom').onclick=()=>setZoom(zoom===1?.8:1);q('#d2-command-input').oninput=e=>filterCmd(e.target.value);qa('#d2-command-list button').forEach(b=>b.onclick=()=>run(b.dataset.cmd));q('#d2-command').onclick=e=>{if(e.target.id==='d2-command')toggleCmd(false)};addEventListener('keydown',e=>{const tag=(e.target.tagName||'').toLowerCase();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();return toggleCmd(true)}if(e.key==='Escape')return toggleCmd(false);if(tag==='input'||tag==='textarea')return;if(e.key.toLowerCase()==='v')setTool('select');if(e.key.toLowerCase()==='f')setTool('frame');if(e.key.toLowerCase()==='t')setTool('text');if(e.key.toLowerCase()==='a')setTool('asset');if(e.key==='0')setZoom(.8);if(e.key==='1')setZoom(1);if((e.metaKey||e.ctrlKey)&&(e.key==='+'||e.key==='=')){e.preventDefault();setZoom(zoom+.1)}if((e.metaKey||e.ctrlKey)&&e.key==='-'){e.preventDefault();setZoom(zoom-.1)}});setZoom(1)})()</script>'''
    return html.replace('</head>',css+'</head>').replace('</body>',shell+js+'</body>').replace('DORÉ DESIGN 1.9 · PROMOTION PIPELINE','DORÉ DESIGN')
